  $cnutjson${"slug": "community-nutrition", "title": "Community Nutrition", "description": "Study of nutrition at community and population levels, emphasizing nutrition epidemiology, community assessment, food and nutrition security, public programs, health behavior, culturally responsive education, participatory planning, implementation, policy, evaluation, sustainable food systems, emergency preparedness, ethics, and advocacy. Students develop a partner-informed intervention proposal addressing an authentic community nutrition priority.", "topics": [{"id": "f70c4c31-b12f-4b5a-a834-e4dce6638246", "type": "topic", "title": "Foundations of Community and Public Health Nutrition", "description": "This opening unit shifts the lens from individual counseling to populations, systems, and prevention. Students learn how community nutrition connects nutrition science, public health practice, dietetics, and collective action.", "children": [{"id": "ad8322c5-a354-4f7a-b3e2-c59275e78719", "type": "subtopic", "title": "Scope, history, and functions of community nutrition", "description": "Establishes what community nutrition professionals do and why population-level action is essential alongside clinical care.", "children": [{"id": "a9263038-9cc9-46ef-ba95-8ce592d300e7", "type": "concept", "title": "Public health versus clinical and community practice"}, {"id": "1de38117-4518-49c4-86ac-6b7c679ade90", "type": "concept", "title": "Primary, secondary, and tertiary prevention"}, {"id": "1359a667-54ec-4b23-8ed9-f1933accf597", "type": "concept", "title": "Historical milestones and changing burden of nutrition-related disease"}]}, {"id": "e4b8198d-9982-413e-948f-ca1eed162586", "type": "subtopic", "title": "Population health, health equity, and structural determinants", "description": "Explains how social conditions, power, and policy shape nutrition opportunities and outcomes.", "children": [{"id": "7a0ffe79-a376-4c05-8b86-14a02b7aef7b", "type": "concept", "title": "Social and commercial determinants of health"}, {"id": "b1735ac9-38da-4e84-a2d1-c8dac2b17a24", "type": "concept", "title": "Structural racism, colonization, poverty, disability, and place"}, {"id": "5d38111b-dc9e-4d3d-939d-fdb7efd98eb0", "type": "concept", "title": "Equality, equity, justice, and proportionate universalism"}]}, {"id": "20c65d84-572c-4157-91c7-daec253ec9eb", "type": "subtopic", "title": "Roles, competencies, and interprofessional practice", "description": "Clarifies how dietitians collaborate with public health, education, agriculture, social services, and community leadership.", "children": [{"id": "d13d2310-1757-4224-a6e5-b5981120a3a7", "type": "concept", "title": "Community nutrition competencies and scope"}, {"id": "81b5507e-bdf0-48df-b9ba-d572ac2b8d5f", "type": "concept", "title": "Interprofessional teams and referral networks"}, {"id": "9f005cf7-5adc-42ff-8acf-ab4b1d5b8ff0", "type": "concept", "title": "Professional boundaries and reflective practice"}]}]}, {"id": "5290ece2-eb97-44e1-94a0-6e61c9759b31", "type": "topic", "title": "Nutrition Epidemiology and Community Data Literacy", "description": "Community decisions should be grounded in trustworthy evidence. This unit builds practical fluency in describing nutrition problems, interpreting population data, and communicating uncertainty without turning the course into an advanced statistics class.", "children": [{"id": "811dd474-5e71-4dcd-a01f-e4cbc3b1a700", "type": "subtopic", "title": "Measures of population nutrition and health", "description": "Introduces the indicators used to describe dietary exposure, nutritional status, and unequal disease burden.", "children": [{"id": "f8486877-ee64-44cc-8c74-10aac941194e", "type": "concept", "title": "Incidence, prevalence, rates, risk, and burden"}, {"id": "6ef3dbae-8727-48e1-a47f-97bce2c79364", "type": "concept", "title": "Anthropometric, biochemical, clinical, dietary, and ecological indicators"}, {"id": "20c0fe7a-b6ed-4af7-b467-6c38fd558228", "type": "concept", "title": "Disaggregation by age, race/ethnicity, income, geography, sex, and disability"}]}, {"id": "a04980f5-0b69-492d-811d-3e8f56f40cac", "type": "subtopic", "title": "Dietary assessment and surveillance", "description": "Shows how population diets are measured and why every method contains error and bias.", "children": [{"id": "2ab2bf67-1e1c-4057-8ae6-9ffe9a2cea69", "type": "concept", "title": "24-hour recalls, food-frequency questionnaires, records, and screeners"}, {"id": "cc979356-adfc-4dac-9640-8842443e0624", "type": "concept", "title": "National and local surveillance systems"}, {"id": "add6ea5b-3b7f-4fcc-885d-847532f28f80", "type": "concept", "title": "Measurement error, under-reporting, cultural validity, and respondent burden"}]}, {"id": "3186089c-a6cf-4714-a62d-038d979fd498", "type": "subtopic", "title": "Evidence appraisal and causal reasoning", "description": "Helps students distinguish association from causation and judge whether evidence is useful for action.", "children": [{"id": "3f6af7e6-de97-4083-9101-bab267e9a8ee", "type": "concept", "title": "Study designs and evidence hierarchies"}, {"id": "a6396332-bdfa-467e-9c67-b706d5df15d4", "type": "concept", "title": "Confounding, selection bias, information bias, and effect modification"}, {"id": "00efedce-ec58-4fb8-aea6-82acf718daf0", "type": "concept", "title": "Absolute versus relative effects and practical significance"}]}, {"id": "e99fd866-92c5-4d36-b1ff-33ff2aa45336", "type": "subtopic", "title": "Data visualization and responsible communication", "description": "Builds the ability to translate data into an accurate, accessible community story.", "children": [{"id": "a64745a1-9064-4922-8b81-9443b4e742e7", "type": "concept", "title": "Choosing denominators and comparison groups"}, {"id": "21f02b63-a04a-4010-a430-d0e9d5e215b6", "type": "concept", "title": "Maps, dashboards, charts, and data storytelling"}, {"id": "44fe21be-92bf-4977-a7bf-d148c488e890", "type": "concept", "title": "Uncertainty, missingness, small numbers, privacy, and stigmatizing displays"}]}]}, {"id": "e3cc2da9-390b-4a64-85c1-92eed0323d58", "type": "topic", "title": "Community Assessment and Asset Mapping", "description": "Effective programs begin with listening and disciplined inquiry. Students learn to define a community with its members, combine multiple data sources, and identify strengths—not only deficits.", "children": [{"id": "ad72d0c3-5d23-49e7-b161-7f5a251b9fab", "type": "subtopic", "title": "Defining community and engaging partners", "description": "Prevents outsiders from imposing artificial boundaries or priorities on people whose lives are affected.", "children": [{"id": "76a3cb32-1bf2-48f0-9bda-7363907dcc3e", "type": "concept", "title": "Geographic, cultural, institutional, identity-based, and virtual communities"}, {"id": "77859a7e-3e54-4a5d-ae18-9f4bca494e89", "type": "concept", "title": "Stakeholder analysis and relationship mapping"}, {"id": "11fcfd6d-7cf8-44ef-80a2-34e168d4b1d9", "type": "concept", "title": "Community advisory structures and shared decision-making"}]}, {"id": "b361b891-139c-4045-aa4b-18a3f61de65e", "type": "subtopic", "title": "Secondary data and environmental scans", "description": "Uses existing evidence efficiently to characterize need, context, and opportunity.", "children": [{"id": "dd859eb9-c781-4187-8ca2-17696d702677", "type": "concept", "title": "Census, vital statistics, food environment, and health datasets"}, {"id": "bc928cfb-de68-4a2c-8466-bbf64170bfd2", "type": "concept", "title": "Policy and service inventories"}, {"id": "66a30890-e1d9-4064-b1d2-b2460241434c", "type": "concept", "title": "Geographic information systems and neighborhood observation"}]}, {"id": "28735441-132c-48f4-be7b-7b3439570384", "type": "subtopic", "title": "Primary and qualitative assessment methods", "description": "Captures lived experience and explanations that administrative data cannot provide.", "children": [{"id": "d988ef47-92fe-4ef0-b1b2-ea9c6a6be74a", "type": "concept", "title": "Surveys, interviews, focus groups, listening sessions, and photovoice"}, {"id": "ca94eaf1-38cc-4110-ac9e-46b3616520d4", "type": "concept", "title": "Sampling, recruitment, accessibility, and language inclusion"}, {"id": "4a531907-dd87-4f7e-8fcd-fcece83e31b5", "type": "concept", "title": "Rapid analysis, triangulation, and member checking"}]}, {"id": "88ce95b0-c8f1-4596-b764-07b5514c3fcb", "type": "subtopic", "title": "Asset mapping, prioritization, and problem framing", "description": "Turns findings into a jointly owned, feasible focus for action.", "children": [{"id": "61932917-ef48-4392-ba53-91b48a5c3386", "type": "concept", "title": "Community capitals, informal networks, and local expertise"}, {"id": "38738f1f-8d89-4d02-823f-32769db6eddb", "type": "concept", "title": "Root-cause analysis and systems maps"}, {"id": "ee06f1d8-600d-4208-92e2-f8483639384d", "type": "concept", "title": "Prioritization criteria: magnitude, severity, inequity, feasibility, and readiness"}]}]}, {"id": "a7e0c761-6fe2-49a4-95c8-8702c561298a", "type": "topic", "title": "Food Security, Food Environments, and Nutrition Equity", "description": "This unit examines why access to adequate, safe, culturally meaningful food is uneven. Students connect household experiences to food systems, labor, housing, transportation, pricing, and discrimination.", "children": [{"id": "57218465-ff88-4326-b996-5f141969205c", "type": "subtopic", "title": "Food security concepts and measurement", "description": "Creates a precise vocabulary for identifying and monitoring constrained food access without blaming households.", "children": [{"id": "b15b2436-ac63-4fd3-a0cd-76f1b9fb2035", "type": "concept", "title": "Food security, insecurity, insufficiency, hunger, and nutrition security"}, {"id": "373b927f-6681-4f7a-b3fb-e357afa56702", "type": "concept", "title": "Household food-security modules and screening tools"}, {"id": "88d82346-471e-4b27-9186-8e5ea91414a7", "type": "concept", "title": "Severity, duration, coping strategies, and stigma"}]}, {"id": "0dfc01b5-1f0d-4feb-88df-16c53a37eec5", "type": "subtopic", "title": "Food environments and commercial influences", "description": "Explores how availability, affordability, marketing, and institutional settings shape choices.", "children": [{"id": "3ab91d73-0ada-4bc6-80e2-4bea8218efd0", "type": "concept", "title": "Retail, school, workplace, healthcare, and digital food environments"}, {"id": "28980579-f08c-486c-b493-dcda1578aa25", "type": "concept", "title": "Price, placement, promotion, and targeted marketing"}, {"id": "135a3e6a-9d9d-4939-ae3e-928250d9a7cd", "type": "concept", "title": "Ultra-processed foods and commercial determinants"}]}, {"id": "15ba2f0e-8efa-40e4-856b-e0f3e4c34288", "type": "subtopic", "title": "Structural drivers and priority populations", "description": "Links inequities to upstream systems rather than individual willpower.", "children": [{"id": "73640285-dd0b-40cf-94f6-4fc4ec5bbc1f", "type": "concept", "title": "Income, housing, transportation, immigration status, and labor conditions"}, {"id": "a8d33af6-7aa2-425c-a59f-ade6924a6fa2", "type": "concept", "title": "Indigenous food sovereignty and racialized food inequities"}, {"id": "45cc8179-57c2-4428-8344-176e01520d70", "type": "concept", "title": "Rural, remote, disability, older-adult, student, and newcomer contexts"}]}, {"id": "825e66b5-c8d2-4c62-9a9c-45d35f84a394", "type": "subtopic", "title": "Dignity-centered and rights-based responses", "description": "Evaluates responses by reach, adequacy, autonomy, cultural fit, and long-term justice.", "children": [{"id": "adbd6155-6b62-4c9d-9e6a-072503d493af", "type": "concept", "title": "Emergency food, cash transfers, social protection, and universal programs"}, {"id": "130aea07-2b83-40fd-8024-ff222af3d580", "type": "concept", "title": "Trauma-informed screening and referral"}, {"id": "de7e8c01-df7d-4eae-97aa-72761a161cf2", "type": "concept", "title": "Right to food, food sovereignty, and anti-stigma design"}]}]}, {"id": "41efd68d-7088-4bf9-8ef3-db615db837b6", "type": "topic", "title": "Public Nutrition Programs and Safety Nets", "description": "Students learn how major nutrition programs operate, whom they reach, and how program rules can either reduce or reproduce inequity. The emphasis is on applying evidence to implementation and improvement.", "children": [{"id": "4eca2076-d0cc-49ed-ae5e-4f2501284cb9", "type": "subtopic", "title": "Maternal, infant, and early-childhood programs", "description": "Examines high-impact supports during sensitive life stages.", "children": [{"id": "46888f88-e31b-4390-8200-2a77e0c3dcf0", "type": "concept", "title": "WIC and breastfeeding support"}, {"id": "26bb6e64-8a59-4b45-a7b0-e719f479e5e8", "type": "concept", "title": "Home visiting and maternal-child health linkages"}, {"id": "abaabbdd-a86a-4620-a7d7-be340be93443", "type": "concept", "title": "Eligibility, participation, retention, and respectful service delivery"}]}, {"id": "17e02ab2-6608-4fdd-809e-08fa1b593a97", "type": "subtopic", "title": "School and child nutrition", "description": "Shows how universal and targeted meal systems influence learning, health, and household budgets.", "children": [{"id": "92e59aae-5762-4626-bffb-329d20304700", "type": "concept", "title": "School breakfast and lunch"}, {"id": "b04bff62-505a-4909-a98c-3c703c1dc87a", "type": "concept", "title": "Summer and after-school meals"}, {"id": "80ff0fc8-2df5-4549-97fb-67c737b183bd", "type": "concept", "title": "Nutrition standards, procurement, stigma, and universal meals"}]}, {"id": "27d4d322-cd08-4965-81cb-81d39d7ae2ba", "type": "subtopic", "title": "Household and older-adult assistance", "description": "Explores benefits and services that improve food purchasing power and access.", "children": [{"id": "12aa2f69-9b9b-4e23-8954-69525d4cca6c", "type": "concept", "title": "SNAP and nutrition incentives"}, {"id": "e8f7ea1f-1f66-436b-96bd-daa2b3c6ea87", "type": "concept", "title": "Congregate and home-delivered meals"}, {"id": "ea946b7b-c394-42dc-af15-2cfb1c08bc08", "type": "concept", "title": "Application burden, benefit adequacy, and outreach"}]}, {"id": "6ee6b72b-5d52-40df-8e5a-bd5afa2de579", "type": "subtopic", "title": "Program administration and quality improvement", "description": "Connects policy design to frontline operations and participant experience.", "children": [{"id": "ba5aa8f9-b968-4996-a2c0-541277fa3337", "type": "concept", "title": "Funding streams, eligibility, certification, and accountability"}, {"id": "9c9e8cff-aabe-4009-a321-e14c139719dd", "type": "concept", "title": "Cross-enrollment and referral systems"}, {"id": "b375348c-0d9b-4d65-838a-87ef8277fe50", "type": "concept", "title": "Process mapping, service data, participant feedback, and continuous improvement"}]}]}, {"id": "da23e18a-312e-40e4-9185-6fa08a73102a", "type": "topic", "title": "Health Behavior Theory and Ecological Intervention Design", "description": "Theory helps explain why a well-intended message may fail and where change is possible. Students use theory as a practical design tool across individual, interpersonal, organizational, community, and policy levels.", "children": [{"id": "8834af38-914a-4b51-847f-cd042626b15f", "type": "subtopic", "title": "Individual and interpersonal theories", "description": "Provides constructs for understanding motivation, skills, confidence, and social influence.", "children": [{"id": "dcfcbcb5-1e20-4a47-ac7f-541d052738f2", "type": "concept", "title": "Health Belief Model"}, {"id": "625bded3-b545-4225-8a7f-9d4e45ed9aba", "type": "concept", "title": "Social Cognitive Theory"}, {"id": "4ad03677-9874-4304-8c65-97b05f68e3d7", "type": "concept", "title": "Theory of Planned Behavior and self-determination"}, {"id": "fa647ac5-c9cb-4fd7-8931-460d4a4c1859", "type": "concept", "title": "Stages of change—uses and limitations"}]}, {"id": "7b757c1f-db44-4a10-ae98-c2b53cb48cef", "type": "subtopic", "title": "Ecological and systems perspectives", "description": "Moves intervention design beyond education-only solutions.", "children": [{"id": "70cb99fc-a1cf-4a3a-9fc4-f295b7acc5fd", "type": "concept", "title": "Social ecological model"}, {"id": "9e9268fd-944e-4d93-8967-b3266e8c07be", "type": "concept", "title": "Systems thinking, feedback loops, and leverage points"}, {"id": "73ee5315-9368-414a-82e0-30884c43e482", "type": "concept", "title": "Diffusion of innovations and social networks"}]}, {"id": "b29f6d45-59f7-4f35-8af6-e306eea437dc", "type": "subtopic", "title": "Selecting and operationalizing theory", "description": "Teaches students to choose constructs based on assessment evidence rather than habit.", "children": [{"id": "efe77edb-60ad-43aa-9612-5927aa7efb4c", "type": "concept", "title": "Theory-to-determinant alignment"}, {"id": "e55e9b95-c2ac-4db0-b63f-8b77a80cffd8", "type": "concept", "title": "Logic of change and testable assumptions"}, {"id": "c8f6991c-7297-4167-a774-e3a8f5b2d3e1", "type": "concept", "title": "Avoiding theory decoration and victim-blaming"}]}, {"id": "7181b30b-0b76-4ed0-9c02-6c2c2954743b", "type": "subtopic", "title": "Behavioral economics and choice architecture", "description": "Considers how defaults, convenience, salience, and incentives can support healthier environments while preserving autonomy.", "children": [{"id": "cf7cb666-f47b-4091-9282-683f90d8533c", "type": "concept", "title": "Defaults, prompts, placement, and friction"}, {"id": "28efd126-6a7d-4166-9be8-95056da6f892", "type": "concept", "title": "Incentives and unintended consequences"}, {"id": "ff443a4a-0972-4c50-9060-b3e0743e7389", "type": "concept", "title": "Ethics of nudging and transparent design"}]}]}, {"id": "63ce332a-49ce-44b3-b6b4-8366f9849517", "type": "topic", "title": "Culturally Responsive Nutrition Education and Communication", "description": "Nutrition education is effective when it is relevant, understandable, respectful, and co-created. Students practice translating evidence into learning experiences and communication products for diverse audiences.", "children": [{"id": "908ba11a-4dc5-44ce-a11c-d974d6a2fb3f", "type": "subtopic", "title": "Culture, foodways, and cultural humility", "description": "Builds curiosity and self-awareness while rejecting stereotypes and one-size-fits-all advice.", "children": [{"id": "1883e81e-e831-4886-9795-88bff42618b9", "type": "concept", "title": "Food identity, migration, religion, family, and tradition"}, {"id": "6b6f699a-ac68-41b0-b7ea-432bf395e4c1", "type": "concept", "title": "Cultural humility, positionality, and power"}, {"id": "cb481e08-c8b3-4d0c-9f5c-f7ff9b0e756f", "type": "concept", "title": "Adaptation versus surface-level translation"}]}, {"id": "51f7a24e-99d9-40be-b9c0-2d33cb26086c", "type": "subtopic", "title": "Learning design and facilitation", "description": "Turns objectives into participatory experiences that build usable knowledge and skills.", "children": [{"id": "6b955323-8e4b-4e0c-aa77-7e50bd916f45", "type": "concept", "title": "Audience analysis and measurable learning objectives"}, {"id": "a5d503df-6b0f-429a-8815-0eedc233a603", "type": "concept", "title": "Adult learning, experiential learning, and peer education"}, {"id": "a17ac62d-159d-4d2c-bdb7-d872f9305c91", "type": "concept", "title": "Lesson sequencing, demonstrations, teach-back, and facilitation"}]}, {"id": "7131ec5f-f9fb-4209-a257-33a6f3ee5f6e", "type": "subtopic", "title": "Health literacy, numeracy, language, and accessibility", "description": "Ensures materials can be understood and used across literacy levels and access needs.", "children": [{"id": "e52b173e-6685-4c69-a0e2-ba9cd4f711eb", "type": "concept", "title": "Plain language and universal precautions"}, {"id": "d71025d3-0156-41f1-b3d0-24b31805d61c", "type": "concept", "title": "Risk and numerical communication"}, {"id": "b30e47de-40b3-4893-adb6-9059a85b338b", "type": "concept", "title": "Interpretation, translation, disability access, and inclusive formats"}]}, {"id": "a48fef95-1c17-4828-8280-12a20c3db5d4", "type": "subtopic", "title": "Digital communication and misinformation", "description": "Prepares students to communicate in online environments shaped by algorithms, influencers, and rapidly spreading claims.", "children": [{"id": "1ec56243-4e3d-409c-9a10-1262b5b8a186", "type": "concept", "title": "Social media campaign design and audience segmentation"}, {"id": "c56cf38f-d992-4956-b3bd-ede3206a6b7e", "type": "concept", "title": "Source verification and prebunking/debunking"}, {"id": "191d5224-937c-4bd1-b869-338c252ee819", "type": "concept", "title": "Ethical storytelling, privacy, and evaluation of digital reach"}]}]}, {"id": "94e6f9ff-ab6e-414a-ba19-423343d6358a", "type": "topic", "title": "Participatory Program Planning and Logic Models", "description": "This unit converts assessment evidence into a coherent, community-owned plan. Students build programs whose activities, resources, outcomes, and assumptions can be explained and tested.", "children": [{"id": "812e3785-3906-4173-9365-c8840fd002c2", "type": "subtopic", "title": "Partnership and participatory planning", "description": "Improves relevance, legitimacy, and sustainability by sharing power throughout the program cycle.", "children": [{"id": "e53a701b-44af-453e-a522-d3e1991a7762", "type": "concept", "title": "Community-based participatory principles"}, {"id": "43310e06-987a-49ac-9dc6-7d5ac3e2beed", "type": "concept", "title": "Compensation, governance, conflict, and accountability"}, {"id": "85ba4c9d-1695-433f-ac42-2cdeb5e13710", "type": "concept", "title": "Coalitions, memoranda of understanding, and facilitation"}]}, {"id": "8191c2af-aef4-497b-bbe8-ca2a9361a55d", "type": "subtopic", "title": "Goals, objectives, and intervention selection", "description": "Creates a defensible line from priority problem to achievable action.", "children": [{"id": "3e4d6fa3-43ba-4e04-8c89-21babc914fd6", "type": "concept", "title": "SMARTIE objectives"}, {"id": "27b77e8b-220c-4d91-9c8e-d00f3c37ff03", "type": "concept", "title": "Evidence-based and practice-based interventions"}, {"id": "eb404e91-a922-4b45-a8f0-e1c199bcc284", "type": "concept", "title": "Adaptation for context while preserving core functions"}]}, {"id": "fa06821b-c28f-47d5-9316-f079f5434973", "type": "subtopic", "title": "Logic models and theories of change", "description": "Makes causal assumptions visible and aligns activities with outcomes.", "children": [{"id": "c5122353-2145-41f4-ad7f-655c56ad9db5", "type": "concept", "title": "Inputs, activities, outputs, and short-/long-term outcomes"}, {"id": "7cebebdd-a3a2-48af-ae0c-3127dc68cc10", "type": "concept", "title": "Context, assumptions, moderators, and unintended effects"}, {"id": "07544796-c2ba-497d-8bb9-9c545498eae9", "type": "concept", "title": "Backward design and contribution versus attribution"}]}, {"id": "9490cae4-fe54-4508-9be0-7cf35d0a2047", "type": "subtopic", "title": "Work plans, budgets, and risk management", "description": "Develops the operational thinking needed to move from an idea to delivery.", "children": [{"id": "ec58f6b2-5488-4693-adea-15a37b228fb3", "type": "concept", "title": "Tasks, timelines, milestones, roles, and dependencies"}, {"id": "73f0c0e9-83e5-460d-b275-30b5a06f1498", "type": "concept", "title": "Direct/indirect costs, in-kind resources, and budget justification"}, {"id": "d0545dae-0cdc-4169-8ab5-ce0b8c8119e9", "type": "concept", "title": "Risk registers, safeguarding, contingency, and data plans"}]}]}, {"id": "15cc69aa-dd21-4288-99c7-e1ea4ee9aaaa", "type": "topic", "title": "Implementation Science, Partnerships, and Workforce", "description": "A program can be evidence-based yet fail in real settings. Students examine adoption, fidelity, adaptation, capacity, and sustainability across organizations and communities.", "children": [{"id": "f3ecfc19-c38f-4cb2-82b5-04546012416b", "type": "subtopic", "title": "Implementation outcomes and context", "description": "Provides a vocabulary for diagnosing why delivery succeeds or stalls.", "children": [{"id": "8695cd3a-09b0-4674-bfcb-f81c27dfb521", "type": "concept", "title": "Acceptability, adoption, appropriateness, feasibility, fidelity, cost, penetration, and sustainability"}, {"id": "3201d7c3-b1b6-419d-9cef-62f6215fe339", "type": "concept", "title": "Inner and outer setting influences"}, {"id": "72c366a2-cad2-4b11-9487-45cbf5fdc888", "type": "concept", "title": "Readiness, climate, leadership, and resources"}]}, {"id": "5657ee00-966f-4795-8665-deebb5852cc2", "type": "subtopic", "title": "Adaptation, fidelity, and quality improvement", "description": "Balances responsiveness to context with protection of the intervention's essential functions.", "children": [{"id": "702d76ab-d23b-4cb5-8b4f-a4d0e78a3f10", "type": "concept", "title": "Core components versus adaptable periphery"}, {"id": "55615544-45db-45b4-8c21-610b03c91182", "type": "concept", "title": "Plan–Do–Study–Act cycles"}, {"id": "4dedefb1-2bd2-488f-bae9-f1ba4e3360e1", "type": "concept", "title": "Implementation logs, fidelity checks, and rapid feedback"}]}, {"id": "5915dfef-eb21-4289-871f-42402a239d38", "type": "subtopic", "title": "Community health workers and peer models", "description": "Examines trusted workforce strategies that bridge services and lived experience.", "children": [{"id": "978b4f48-a59c-4880-a74d-8996970aaa79", "type": "concept", "title": "Roles, training, supervision, compensation, and career pathways"}, {"id": "813537d9-d92c-4dc8-9f8d-c1f7b31c8d17", "type": "concept", "title": "Peer educators, navigators, and promotores"}, {"id": "dc9dd1fe-0e40-4265-b5e3-4d6b999acfae", "type": "concept", "title": "Role clarity, burnout, safety, and ethical employment"}]}, {"id": "93002823-27f8-4cf3-8ab5-176ac5ab752d", "type": "subtopic", "title": "Sustainability and scale", "description": "Encourages planning for durable benefit beyond a pilot or grant period.", "children": [{"id": "44404351-e6a9-48a4-9a13-48099acf5493", "type": "concept", "title": "Institutionalization, financing, policy integration, and ownership"}, {"id": "7418f088-0f64-4d23-aaed-768c288a7a6c", "type": "concept", "title": "Scale-up, spread, and adaptation across sites"}, {"id": "f934cdb5-3ece-4841-a678-4f8a75285315", "type": "concept", "title": "De-implementation of ineffective or harmful practices"}]}]}, {"id": "f2005b21-0c72-4abf-97d6-b5d3e58de893", "type": "topic", "title": "Nutrition Policy, Advocacy, and Political Economy", "description": "Population nutrition is shaped by laws, budgets, institutions, and competing interests. Students learn to analyze policy options and communicate evidence within ethical professional boundaries.", "children": [{"id": "cf31d372-49cf-4eb5-a8d6-8fb46b57f9a0", "type": "subtopic", "title": "Policy process and instruments", "description": "Explains where and how nutrition policy decisions are made.", "children": [{"id": "92112f66-c72e-48ce-96af-53f2aca11c01", "type": "concept", "title": "Agenda setting, formulation, adoption, implementation, and evaluation"}, {"id": "ad2ea169-0da4-4c56-95a3-45d7a8b6fe96", "type": "concept", "title": "Regulation, taxation, subsidies, standards, procurement, and information tools"}, {"id": "0af6e606-9950-4552-95ca-b21293d6de1d", "type": "concept", "title": "Federal, state/provincial, local, institutional, and global authority"}]}, {"id": "c61cd615-3954-4fd5-aa27-8418953dc9c1", "type": "subtopic", "title": "Policy analysis", "description": "Provides a structured way to compare options beyond whether they sound appealing.", "children": [{"id": "8c0449f5-0a31-42ce-8b32-3af3a276edd0", "type": "concept", "title": "Effectiveness, equity, feasibility, cost, acceptability, and enforceability"}, {"id": "6f0ac343-b757-4975-9915-277d599bec64", "type": "concept", "title": "Distributional impact and health impact assessment"}, {"id": "718f017c-f72d-4b68-9c1f-cacee609d6c3", "type": "concept", "title": "Unintended consequences and policy coherence"}]}, {"id": "162a64ee-04e0-4ded-924e-14206087560b", "type": "subtopic", "title": "Advocacy and strategic communication", "description": "Builds lawful, evidence-informed participation in public decision-making.", "children": [{"id": "50040c30-eb6b-447a-888f-e5abe177984c", "type": "concept", "title": "Stakeholder and power mapping"}, {"id": "b584f27f-d73e-47e7-b3cf-695b16182054", "type": "concept", "title": "Policy briefs, testimony, public comment, and media engagement"}, {"id": "49efaf61-4687-426c-9416-4b338314fe79", "type": "concept", "title": "Coalition strategy and grassroots/grasstops approaches"}]}, {"id": "2293d2cf-132c-451c-879b-3f2d0f152f8b", "type": "subtopic", "title": "Industry influence and conflicts of interest", "description": "Develops critical awareness of lobbying, sponsorship, research funding, and corporate political activity.", "children": [{"id": "1db3f6a9-7c6e-4bdb-b5b5-06b3e9d8a048", "type": "concept", "title": "Commercial determinants and policy interference"}, {"id": "593528c3-3687-4caa-8c6a-2e98adc73617", "type": "concept", "title": "Transparency, disclosure, and conflict-management policies"}, {"id": "cdc617cc-873c-43c0-9104-1abd3472ace1", "type": "concept", "title": "Responsible public–private engagement"}]}]}, {"id": "d9b80662-3dfd-4c7e-8f90-8c62ef82a878", "type": "topic", "title": "Program Evaluation, Economic Thinking, and Learning", "description": "Evaluation is not an afterthought; it is how communities and funders learn whether a program was delivered, whom it reached, what changed, and at what cost. Students design feasible mixed-method evaluations.", "children": [{"id": "862f4089-b6c0-4f42-881b-a54ee81aa1c0", "type": "subtopic", "title": "Evaluation questions and designs", "description": "Aligns evaluation effort with decisions stakeholders actually need to make.", "children": [{"id": "e36c67f7-d79d-48be-8ca7-22fac3a8f635", "type": "concept", "title": "Formative, process, outcome, impact, and developmental evaluation"}, {"id": "9867b665-94be-4e21-9c49-b455914acb6e", "type": "concept", "title": "Experimental, quasi-experimental, pre–post, and contribution designs"}, {"id": "7aede296-0363-4cf9-898e-37e362fc79df", "type": "concept", "title": "Evaluability, comparison groups, and threats to validity"}]}, {"id": "4ec05174-8d9c-4985-823b-5240f19c39a9", "type": "subtopic", "title": "Indicators, measurement, and data collection", "description": "Translates objectives into valid, feasible, and equitable measures.", "children": [{"id": "952d63dc-de50-4348-9e47-186ea0ed8140", "type": "concept", "title": "Reach, dose, fidelity, behavior, environment, and health outcomes"}, {"id": "3313135f-109b-450d-812d-e2363f905100", "type": "concept", "title": "Quantitative and qualitative measures"}, {"id": "e62e3825-1c6a-4e8c-a76f-a6d15034bad6", "type": "concept", "title": "Validity, reliability, responsiveness, burden, and cultural relevance"}]}, {"id": "ca889ea3-15ab-4c63-a88e-d82248143622", "type": "subtopic", "title": "Analysis, interpretation, and equity", "description": "Teaches students to judge patterns carefully and avoid averages that hide differential effects.", "children": [{"id": "95552941-cc98-4a25-aa68-d4f5818acd9b", "type": "concept", "title": "Descriptive analysis and meaningful change"}, {"id": "1809fcfe-d209-410c-b6da-dcc6e4fa9643", "type": "concept", "title": "Subgroup and intersectional analysis"}, {"id": "4b9893c5-e067-4b39-83af-13646c4e0b81", "type": "concept", "title": "Triangulation, negative cases, and unintended outcomes"}]}, {"id": "e8d3caef-cc1d-4cc4-b6dc-db98214eb445", "type": "subtopic", "title": "Economic and dissemination considerations", "description": "Introduces resource stewardship and ensures findings return to those who contributed.", "children": [{"id": "530dfab4-ade6-446d-87e4-9f7f92599352", "type": "concept", "title": "Cost description, cost-effectiveness, affordability, and budget impact"}, {"id": "df0f8506-59a6-41a0-a229-14d6a5e6d2fc", "type": "concept", "title": "Data dashboards, briefs, presentations, and community reporting"}, {"id": "6f354d24-ede1-473d-a79b-a66bdf15fc43", "type": "concept", "title": "Utilization-focused recommendations and learning cycles"}]}]}, {"id": "ebf11d95-8e36-4587-a6e7-b46955e39e7b", "type": "topic", "title": "Sustainable Food Systems, Climate, and Emergency Nutrition", "description": "Nutrition security depends on resilient ecological and social systems. Students analyze food-system trade-offs and prepare for disruptions that disproportionately affect communities already facing inequity.", "children": [{"id": "2f6bbf37-371e-49ca-9d1b-d8f71ef5e499", "type": "subtopic", "title": "Food systems and sustainability", "description": "Connects diets with production, processing, distribution, labor, waste, and ecological limits.", "children": [{"id": "7df6d8ac-a2b7-403f-96ac-407213805a68", "type": "concept", "title": "Food-system actors and value chains"}, {"id": "2f6d9e82-ca08-4d4c-b899-b2b5bcbfd143", "type": "concept", "title": "Diet quality, environmental footprints, biodiversity, and animal welfare"}, {"id": "175b4af9-e6a8-49e0-9593-1c068541432e", "type": "concept", "title": "Just transition, labor conditions, and fair livelihoods"}]}, {"id": "8422e5c8-72b0-426d-9550-dbe284036d5c", "type": "subtopic", "title": "Local and institutional food strategies", "description": "Evaluates place-based approaches without assuming local automatically means equitable or sustainable.", "children": [{"id": "f1831878-6264-4862-87c7-9c6b105ed93b", "type": "concept", "title": "Farm-to-school, food hubs, gardens, and urban agriculture"}, {"id": "0553a2a8-1049-454d-9c75-d19b10ed7ef3", "type": "concept", "title": "Values-based procurement and institutional purchasing"}, {"id": "097c7aa7-67d5-4efd-babd-618dd6635156", "type": "concept", "title": "Food loss, waste prevention, recovery, and composting"}]}, {"id": "675c60af-53ea-4290-98c9-92c32c3fb1a2", "type": "subtopic", "title": "Climate change and nutrition", "description": "Explains pathways from climate hazards to food availability, affordability, safety, and disease.", "children": [{"id": "5f230110-4e09-4280-a571-61a3bdfed2b2", "type": "concept", "title": "Heat, drought, flooding, wildfire, and supply disruption"}, {"id": "413fd85e-cd32-47f4-b763-446e7cef6a28", "type": "concept", "title": "Climate-sensitive malnutrition and foodborne risk"}, {"id": "6bec9ee0-096c-4d3f-8044-747e59f556bc", "type": "concept", "title": "Mitigation, adaptation, resilience, and climate justice"}]}, {"id": "8d44cc99-e917-4b8b-9043-bac7216f3243", "type": "subtopic", "title": "Emergency and humanitarian nutrition", "description": "Builds readiness for ethical nutrition response during disasters and displacement.", "children": [{"id": "cf2d4dd3-a54f-4884-8963-3d0f448e9ffc", "type": "concept", "title": "Emergency preparedness and continuity of nutrition services"}, {"id": "72410084-642b-4777-8ba2-b65af76a1097", "type": "concept", "title": "Rapid assessment, shelters, feeding operations, and special dietary needs"}, {"id": "ba25053e-76d3-4839-91c0-6159a8e82577", "type": "concept", "title": "Infant feeding in emergencies, safeguarding, coordination, and recovery"}]}]}, {"id": "ec7e9ce8-36ba-424b-9752-041c67acdea4", "type": "topic", "title": "Ethics, Law, and Responsible Community Practice", "description": "Community nutrition professionals hold responsibilities to individuals, communities, employers, funders, and the public. This unit makes ethical reasoning, legal awareness, and responsible data practice explicit.", "children": [{"id": "c306befb-b807-4ea1-9bb7-b0a357e83bc9", "type": "subtopic", "title": "Ethical frameworks and professional conduct", "description": "Provides a disciplined way to resolve tensions among benefit, autonomy, justice, and duty.", "children": [{"id": "f039e635-ada2-467a-94c8-84eb24b65ab7", "type": "concept", "title": "Beneficence, nonmaleficence, autonomy, justice, solidarity, and reciprocity"}, {"id": "fd747933-3273-4aca-970c-1f59b907a002", "type": "concept", "title": "Professional codes, competence, and accountability"}, {"id": "0643af56-0414-49e5-a3b3-0b8c2feba984", "type": "concept", "title": "Moral distress, dual loyalty, and escalation pathways"}]}, {"id": "acab6939-c083-4bfa-b9fb-6394e87d91e9", "type": "subtopic", "title": "Consent, privacy, and community data governance", "description": "Protects participants while recognizing that communities can also experience collective harms.", "children": [{"id": "001f6c7e-aba5-48a5-8b09-e04b64fbb1df", "type": "concept", "title": "Informed consent and assent"}, {"id": "51bc5cd6-8e46-4ded-bb39-ee6ab7a08a76", "type": "concept", "title": "Confidentiality, data minimization, security, and secondary use"}, {"id": "afb99144-7ed0-48c6-8564-cb4b4dd69be8", "type": "concept", "title": "Data ownership, Indigenous data sovereignty, and community review"}]}, {"id": "7f2a6cb4-d5e8-4f5f-af6a-0e65d52f788d", "type": "subtopic", "title": "Research and evaluation ethics", "description": "Distinguishes service improvement from research while applying safeguards to both.", "children": [{"id": "def76a18-f2bd-4079-bb3c-b2cb19bed6a1", "type": "concept", "title": "Human-subjects review and quality-improvement boundaries"}, {"id": "ee2857ce-44f5-4567-8ed5-c1f769700c90", "type": "concept", "title": "Recruitment, incentives, vulnerable populations, and risk"}, {"id": "88321245-88f8-4177-add5-7fe74958b72e", "type": "concept", "title": "Returning results and benefit sharing"}]}, {"id": "1665ee96-0d87-4f48-ba5c-17b2ca8fcf72", "type": "subtopic", "title": "Stigma, weight bias, and respectful practice", "description": "Prevents nutrition interventions from reinforcing shame, discrimination, or eating pathology.", "children": [{"id": "aeb7e1b9-b393-4f3b-ad95-7b67901e02bc", "type": "concept", "title": "Person-first and identity-affirming language"}, {"id": "ab29980d-35d7-4896-a2fd-b2dc3b7cc3ec", "type": "concept", "title": "Weight-inclusive and trauma-informed approaches"}, {"id": "bcd40de1-a97f-45b9-8159-9e7b53943bfc", "type": "concept", "title": "Image selection, messaging audits, and harm monitoring"}]}]}, {"id": "55b0d84b-5488-49e2-8f22-c05f6744812e", "type": "topic", "title": "Community Nutrition Intervention Capstone", "description": "The capstone integrates assessment, theory, planning, implementation, evaluation, and communication into a partner-informed intervention proposal. It demonstrates readiness to contribute responsibly to real community nutrition work.", "children": [{"id": "5f505c4f-5074-4b69-bf0a-a1daa4f730d0", "type": "subtopic", "title": "Partner brief and evidence synthesis", "description": "Defines the community priority and decision context using credible data and community knowledge.", "children": [{"id": "20c59566-9583-417a-a082-9ca1be1b7156", "type": "concept", "title": "Community profile and asset/needs synthesis"}, {"id": "1181865c-4d0e-44ac-9c17-51e12aba50b9", "type": "concept", "title": "Stakeholder, equity, and systems analysis"}, {"id": "08e30da5-18b0-42df-9b6c-8bc6e7f0676c", "type": "concept", "title": "Focused evidence review and intervention rationale"}]}, {"id": "b1445f6d-41f6-4b4f-a2ff-e8e07d27ce02", "type": "subtopic", "title": "Intervention and implementation plan", "description": "Specifies what will happen, for whom, by whom, and under what conditions.", "children": [{"id": "9f87b2cb-0254-4762-9712-211ddfd261a8", "type": "concept", "title": "Theory of change and logic model"}, {"id": "99a75d55-0c0c-4492-a59d-7fe4e140a62e", "type": "concept", "title": "Culturally responsive activities and materials"}, {"id": "4c929867-7b17-4f79-8246-781c535b4b3d", "type": "concept", "title": "Work plan, roles, budget, adaptation, risk, and sustainability"}]}, {"id": "c9eee684-da01-49a2-bdc9-540b0becfce0", "type": "subtopic", "title": "Evaluation and knowledge-mobilization plan", "description": "Ensures the proposal can generate useful learning and communicate it accessibly.", "children": [{"id": "96a7f490-476d-47eb-a617-1ff747ce7ba5", "type": "concept", "title": "Evaluation questions, indicators, methods, and analysis"}, {"id": "63ba41bd-3131-4ed7-9ce6-83214842984a", "type": "concept", "title": "Ethics, privacy, and data governance"}, {"id": "d21da3bf-3eb5-4d37-9982-500c7d56bdf5", "type": "concept", "title": "Community-facing product, policy brief, and professional presentation"}]}, {"id": "cea56cc2-3d09-4cdd-b116-b5ad77ac224f", "type": "subtopic", "title": "Peer review and reflective practice", "description": "Develops the ability to give, receive, and apply critique while examining one's own assumptions and power.", "children": [{"id": "c4097528-8e41-43ba-85f6-c9368140d064", "type": "concept", "title": "Structured peer and partner feedback"}, {"id": "8c9bae07-627b-48fb-b25c-aa2dd759849c", "type": "concept", "title": "Revision memo and decision log"}, {"id": "1506961e-bcc0-4fc1-bb52-4d33fb76f73e", "type": "concept", "title": "Individual reflection on positionality, competence, and next steps"}]}]}], "dbBacked": true}$cnutjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'community-nutrition'
);

update public.learning_paths
set
  title = 'Community Nutrition',
  goal = 'Community Nutrition',
  summary = 'Study of nutrition at community and population levels, emphasizing nutrition epidemiology, community assessment, food and nutrition security, public programs, health behavior, culturally responsive education, participatory planning, implementation, policy, evaluation, sustainable food systems, emergency preparedness, ethics, and advocacy. Students develop a partner-informed intervention proposal addressing an authentic community nutrition priority.',
  data = $cnutjson${"slug": "community-nutrition", "title": "Community Nutrition", "description": "Study of nutrition at community and population levels, emphasizing nutrition epidemiology, community assessment, food and nutrition security, public programs, health behavior, culturally responsive education, participatory planning, implementation, policy, evaluation, sustainable food systems, emergency preparedness, ethics, and advocacy. Students develop a partner-informed intervention proposal addressing an authentic community nutrition priority.", "topics": [{"id": "f70c4c31-b12f-4b5a-a834-e4dce6638246", "type": "topic", "title": "Foundations of Community and Public Health Nutrition", "description": "This opening unit shifts the lens from individual counseling to populations, systems, and prevention. Students learn how community nutrition connects nutrition science, public health practice, dietetics, and collective action.", "children": [{"id": "ad8322c5-a354-4f7a-b3e2-c59275e78719", "type": "subtopic", "title": "Scope, history, and functions of community nutrition", "description": "Establishes what community nutrition professionals do and why population-level action is essential alongside clinical care.", "children": [{"id": "a9263038-9cc9-46ef-ba95-8ce592d300e7", "type": "concept", "title": "Public health versus clinical and community practice"}, {"id": "1de38117-4518-49c4-86ac-6b7c679ade90", "type": "concept", "title": "Primary, secondary, and tertiary prevention"}, {"id": "1359a667-54ec-4b23-8ed9-f1933accf597", "type": "concept", "title": "Historical milestones and changing burden of nutrition-related disease"}]}, {"id": "e4b8198d-9982-413e-948f-ca1eed162586", "type": "subtopic", "title": "Population health, health equity, and structural determinants", "description": "Explains how social conditions, power, and policy shape nutrition opportunities and outcomes.", "children": [{"id": "7a0ffe79-a376-4c05-8b86-14a02b7aef7b", "type": "concept", "title": "Social and commercial determinants of health"}, {"id": "b1735ac9-38da-4e84-a2d1-c8dac2b17a24", "type": "concept", "title": "Structural racism, colonization, poverty, disability, and place"}, {"id": "5d38111b-dc9e-4d3d-939d-fdb7efd98eb0", "type": "concept", "title": "Equality, equity, justice, and proportionate universalism"}]}, {"id": "20c65d84-572c-4157-91c7-daec253ec9eb", "type": "subtopic", "title": "Roles, competencies, and interprofessional practice", "description": "Clarifies how dietitians collaborate with public health, education, agriculture, social services, and community leadership.", "children": [{"id": "d13d2310-1757-4224-a6e5-b5981120a3a7", "type": "concept", "title": "Community nutrition competencies and scope"}, {"id": "81b5507e-bdf0-48df-b9ba-d572ac2b8d5f", "type": "concept", "title": "Interprofessional teams and referral networks"}, {"id": "9f005cf7-5adc-42ff-8acf-ab4b1d5b8ff0", "type": "concept", "title": "Professional boundaries and reflective practice"}]}]}, {"id": "5290ece2-eb97-44e1-94a0-6e61c9759b31", "type": "topic", "title": "Nutrition Epidemiology and Community Data Literacy", "description": "Community decisions should be grounded in trustworthy evidence. This unit builds practical fluency in describing nutrition problems, interpreting population data, and communicating uncertainty without turning the course into an advanced statistics class.", "children": [{"id": "811dd474-5e71-4dcd-a01f-e4cbc3b1a700", "type": "subtopic", "title": "Measures of population nutrition and health", "description": "Introduces the indicators used to describe dietary exposure, nutritional status, and unequal disease burden.", "children": [{"id": "f8486877-ee64-44cc-8c74-10aac941194e", "type": "concept", "title": "Incidence, prevalence, rates, risk, and burden"}, {"id": "6ef3dbae-8727-48e1-a47f-97bce2c79364", "type": "concept", "title": "Anthropometric, biochemical, clinical, dietary, and ecological indicators"}, {"id": "20c0fe7a-b6ed-4af7-b467-6c38fd558228", "type": "concept", "title": "Disaggregation by age, race/ethnicity, income, geography, sex, and disability"}]}, {"id": "a04980f5-0b69-492d-811d-3e8f56f40cac", "type": "subtopic", "title": "Dietary assessment and surveillance", "description": "Shows how population diets are measured and why every method contains error and bias.", "children": [{"id": "2ab2bf67-1e1c-4057-8ae6-9ffe9a2cea69", "type": "concept", "title": "24-hour recalls, food-frequency questionnaires, records, and screeners"}, {"id": "cc979356-adfc-4dac-9640-8842443e0624", "type": "concept", "title": "National and local surveillance systems"}, {"id": "add6ea5b-3b7f-4fcc-885d-847532f28f80", "type": "concept", "title": "Measurement error, under-reporting, cultural validity, and respondent burden"}]}, {"id": "3186089c-a6cf-4714-a62d-038d979fd498", "type": "subtopic", "title": "Evidence appraisal and causal reasoning", "description": "Helps students distinguish association from causation and judge whether evidence is useful for action.", "children": [{"id": "3f6af7e6-de97-4083-9101-bab267e9a8ee", "type": "concept", "title": "Study designs and evidence hierarchies"}, {"id": "a6396332-bdfa-467e-9c67-b706d5df15d4", "type": "concept", "title": "Confounding, selection bias, information bias, and effect modification"}, {"id": "00efedce-ec58-4fb8-aea6-82acf718daf0", "type": "concept", "title": "Absolute versus relative effects and practical significance"}]}, {"id": "e99fd866-92c5-4d36-b1ff-33ff2aa45336", "type": "subtopic", "title": "Data visualization and responsible communication", "description": "Builds the ability to translate data into an accurate, accessible community story.", "children": [{"id": "a64745a1-9064-4922-8b81-9443b4e742e7", "type": "concept", "title": "Choosing denominators and comparison groups"}, {"id": "21f02b63-a04a-4010-a430-d0e9d5e215b6", "type": "concept", "title": "Maps, dashboards, charts, and data storytelling"}, {"id": "44fe21be-92bf-4977-a7bf-d148c488e890", "type": "concept", "title": "Uncertainty, missingness, small numbers, privacy, and stigmatizing displays"}]}]}, {"id": "e3cc2da9-390b-4a64-85c1-92eed0323d58", "type": "topic", "title": "Community Assessment and Asset Mapping", "description": "Effective programs begin with listening and disciplined inquiry. Students learn to define a community with its members, combine multiple data sources, and identify strengths—not only deficits.", "children": [{"id": "ad72d0c3-5d23-49e7-b161-7f5a251b9fab", "type": "subtopic", "title": "Defining community and engaging partners", "description": "Prevents outsiders from imposing artificial boundaries or priorities on people whose lives are affected.", "children": [{"id": "76a3cb32-1bf2-48f0-9bda-7363907dcc3e", "type": "concept", "title": "Geographic, cultural, institutional, identity-based, and virtual communities"}, {"id": "77859a7e-3e54-4a5d-ae18-9f4bca494e89", "type": "concept", "title": "Stakeholder analysis and relationship mapping"}, {"id": "11fcfd6d-7cf8-44ef-80a2-34e168d4b1d9", "type": "concept", "title": "Community advisory structures and shared decision-making"}]}, {"id": "b361b891-139c-4045-aa4b-18a3f61de65e", "type": "subtopic", "title": "Secondary data and environmental scans", "description": "Uses existing evidence efficiently to characterize need, context, and opportunity.", "children": [{"id": "dd859eb9-c781-4187-8ca2-17696d702677", "type": "concept", "title": "Census, vital statistics, food environment, and health datasets"}, {"id": "bc928cfb-de68-4a2c-8466-bbf64170bfd2", "type": "concept", "title": "Policy and service inventories"}, {"id": "66a30890-e1d9-4064-b1d2-b2460241434c", "type": "concept", "title": "Geographic information systems and neighborhood observation"}]}, {"id": "28735441-132c-48f4-be7b-7b3439570384", "type": "subtopic", "title": "Primary and qualitative assessment methods", "description": "Captures lived experience and explanations that administrative data cannot provide.", "children": [{"id": "d988ef47-92fe-4ef0-b1b2-ea9c6a6be74a", "type": "concept", "title": "Surveys, interviews, focus groups, listening sessions, and photovoice"}, {"id": "ca94eaf1-38cc-4110-ac9e-46b3616520d4", "type": "concept", "title": "Sampling, recruitment, accessibility, and language inclusion"}, {"id": "4a531907-dd87-4f7e-8fcd-fcece83e31b5", "type": "concept", "title": "Rapid analysis, triangulation, and member checking"}]}, {"id": "88ce95b0-c8f1-4596-b764-07b5514c3fcb", "type": "subtopic", "title": "Asset mapping, prioritization, and problem framing", "description": "Turns findings into a jointly owned, feasible focus for action.", "children": [{"id": "61932917-ef48-4392-ba53-91b48a5c3386", "type": "concept", "title": "Community capitals, informal networks, and local expertise"}, {"id": "38738f1f-8d89-4d02-823f-32769db6eddb", "type": "concept", "title": "Root-cause analysis and systems maps"}, {"id": "ee06f1d8-600d-4208-92e2-f8483639384d", "type": "concept", "title": "Prioritization criteria: magnitude, severity, inequity, feasibility, and readiness"}]}]}, {"id": "a7e0c761-6fe2-49a4-95c8-8702c561298a", "type": "topic", "title": "Food Security, Food Environments, and Nutrition Equity", "description": "This unit examines why access to adequate, safe, culturally meaningful food is uneven. Students connect household experiences to food systems, labor, housing, transportation, pricing, and discrimination.", "children": [{"id": "57218465-ff88-4326-b996-5f141969205c", "type": "subtopic", "title": "Food security concepts and measurement", "description": "Creates a precise vocabulary for identifying and monitoring constrained food access without blaming households.", "children": [{"id": "b15b2436-ac63-4fd3-a0cd-76f1b9fb2035", "type": "concept", "title": "Food security, insecurity, insufficiency, hunger, and nutrition security"}, {"id": "373b927f-6681-4f7a-b3fb-e357afa56702", "type": "concept", "title": "Household food-security modules and screening tools"}, {"id": "88d82346-471e-4b27-9186-8e5ea91414a7", "type": "concept", "title": "Severity, duration, coping strategies, and stigma"}]}, {"id": "0dfc01b5-1f0d-4feb-88df-16c53a37eec5", "type": "subtopic", "title": "Food environments and commercial influences", "description": "Explores how availability, affordability, marketing, and institutional settings shape choices.", "children": [{"id": "3ab91d73-0ada-4bc6-80e2-4bea8218efd0", "type": "concept", "title": "Retail, school, workplace, healthcare, and digital food environments"}, {"id": "28980579-f08c-486c-b493-dcda1578aa25", "type": "concept", "title": "Price, placement, promotion, and targeted marketing"}, {"id": "135a3e6a-9d9d-4939-ae3e-928250d9a7cd", "type": "concept", "title": "Ultra-processed foods and commercial determinants"}]}, {"id": "15ba2f0e-8efa-40e4-856b-e0f3e4c34288", "type": "subtopic", "title": "Structural drivers and priority populations", "description": "Links inequities to upstream systems rather than individual willpower.", "children": [{"id": "73640285-dd0b-40cf-94f6-4fc4ec5bbc1f", "type": "concept", "title": "Income, housing, transportation, immigration status, and labor conditions"}, {"id": "a8d33af6-7aa2-425c-a59f-ade6924a6fa2", "type": "concept", "title": "Indigenous food sovereignty and racialized food inequities"}, {"id": "45cc8179-57c2-4428-8344-176e01520d70", "type": "concept", "title": "Rural, remote, disability, older-adult, student, and newcomer contexts"}]}, {"id": "825e66b5-c8d2-4c62-9a9c-45d35f84a394", "type": "subtopic", "title": "Dignity-centered and rights-based responses", "description": "Evaluates responses by reach, adequacy, autonomy, cultural fit, and long-term justice.", "children": [{"id": "adbd6155-6b62-4c9d-9e6a-072503d493af", "type": "concept", "title": "Emergency food, cash transfers, social protection, and universal programs"}, {"id": "130aea07-2b83-40fd-8024-ff222af3d580", "type": "concept", "title": "Trauma-informed screening and referral"}, {"id": "de7e8c01-df7d-4eae-97aa-72761a161cf2", "type": "concept", "title": "Right to food, food sovereignty, and anti-stigma design"}]}]}, {"id": "41efd68d-7088-4bf9-8ef3-db615db837b6", "type": "topic", "title": "Public Nutrition Programs and Safety Nets", "description": "Students learn how major nutrition programs operate, whom they reach, and how program rules can either reduce or reproduce inequity. The emphasis is on applying evidence to implementation and improvement.", "children": [{"id": "4eca2076-d0cc-49ed-ae5e-4f2501284cb9", "type": "subtopic", "title": "Maternal, infant, and early-childhood programs", "description": "Examines high-impact supports during sensitive life stages.", "children": [{"id": "46888f88-e31b-4390-8200-2a77e0c3dcf0", "type": "concept", "title": "WIC and breastfeeding support"}, {"id": "26bb6e64-8a59-4b45-a7b0-e719f479e5e8", "type": "concept", "title": "Home visiting and maternal-child health linkages"}, {"id": "abaabbdd-a86a-4620-a7d7-be340be93443", "type": "concept", "title": "Eligibility, participation, retention, and respectful service delivery"}]}, {"id": "17e02ab2-6608-4fdd-809e-08fa1b593a97", "type": "subtopic", "title": "School and child nutrition", "description": "Shows how universal and targeted meal systems influence learning, health, and household budgets.", "children": [{"id": "92e59aae-5762-4626-bffb-329d20304700", "type": "concept", "title": "School breakfast and lunch"}, {"id": "b04bff62-505a-4909-a98c-3c703c1dc87a", "type": "concept", "title": "Summer and after-school meals"}, {"id": "80ff0fc8-2df5-4549-97fb-67c737b183bd", "type": "concept", "title": "Nutrition standards, procurement, stigma, and universal meals"}]}, {"id": "27d4d322-cd08-4965-81cb-81d39d7ae2ba", "type": "subtopic", "title": "Household and older-adult assistance", "description": "Explores benefits and services that improve food purchasing power and access.", "children": [{"id": "12aa2f69-9b9b-4e23-8954-69525d4cca6c", "type": "concept", "title": "SNAP and nutrition incentives"}, {"id": "e8f7ea1f-1f66-436b-96bd-daa2b3c6ea87", "type": "concept", "title": "Congregate and home-delivered meals"}, {"id": "ea946b7b-c394-42dc-af15-2cfb1c08bc08", "type": "concept", "title": "Application burden, benefit adequacy, and outreach"}]}, {"id": "6ee6b72b-5d52-40df-8e5a-bd5afa2de579", "type": "subtopic", "title": "Program administration and quality improvement", "description": "Connects policy design to frontline operations and participant experience.", "children": [{"id": "ba5aa8f9-b968-4996-a2c0-541277fa3337", "type": "concept", "title": "Funding streams, eligibility, certification, and accountability"}, {"id": "9c9e8cff-aabe-4009-a321-e14c139719dd", "type": "concept", "title": "Cross-enrollment and referral systems"}, {"id": "b375348c-0d9b-4d65-838a-87ef8277fe50", "type": "concept", "title": "Process mapping, service data, participant feedback, and continuous improvement"}]}]}, {"id": "da23e18a-312e-40e4-9185-6fa08a73102a", "type": "topic", "title": "Health Behavior Theory and Ecological Intervention Design", "description": "Theory helps explain why a well-intended message may fail and where change is possible. Students use theory as a practical design tool across individual, interpersonal, organizational, community, and policy levels.", "children": [{"id": "8834af38-914a-4b51-847f-cd042626b15f", "type": "subtopic", "title": "Individual and interpersonal theories", "description": "Provides constructs for understanding motivation, skills, confidence, and social influence.", "children": [{"id": "dcfcbcb5-1e20-4a47-ac7f-541d052738f2", "type": "concept", "title": "Health Belief Model"}, {"id": "625bded3-b545-4225-8a7f-9d4e45ed9aba", "type": "concept", "title": "Social Cognitive Theory"}, {"id": "4ad03677-9874-4304-8c65-97b05f68e3d7", "type": "concept", "title": "Theory of Planned Behavior and self-determination"}, {"id": "fa647ac5-c9cb-4fd7-8931-460d4a4c1859", "type": "concept", "title": "Stages of change—uses and limitations"}]}, {"id": "7b757c1f-db44-4a10-ae98-c2b53cb48cef", "type": "subtopic", "title": "Ecological and systems perspectives", "description": "Moves intervention design beyond education-only solutions.", "children": [{"id": "70cb99fc-a1cf-4a3a-9fc4-f295b7acc5fd", "type": "concept", "title": "Social ecological model"}, {"id": "9e9268fd-944e-4d93-8967-b3266e8c07be", "type": "concept", "title": "Systems thinking, feedback loops, and leverage points"}, {"id": "73ee5315-9368-414a-82e0-30884c43e482", "type": "concept", "title": "Diffusion of innovations and social networks"}]}, {"id": "b29f6d45-59f7-4f35-8af6-e306eea437dc", "type": "subtopic", "title": "Selecting and operationalizing theory", "description": "Teaches students to choose constructs based on assessment evidence rather than habit.", "children": [{"id": "efe77edb-60ad-43aa-9612-5927aa7efb4c", "type": "concept", "title": "Theory-to-determinant alignment"}, {"id": "e55e9b95-c2ac-4db0-b63f-8b77a80cffd8", "type": "concept", "title": "Logic of change and testable assumptions"}, {"id": "c8f6991c-7297-4167-a774-e3a8f5b2d3e1", "type": "concept", "title": "Avoiding theory decoration and victim-blaming"}]}, {"id": "7181b30b-0b76-4ed0-9c02-6c2c2954743b", "type": "subtopic", "title": "Behavioral economics and choice architecture", "description": "Considers how defaults, convenience, salience, and incentives can support healthier environments while preserving autonomy.", "children": [{"id": "cf7cb666-f47b-4091-9282-683f90d8533c", "type": "concept", "title": "Defaults, prompts, placement, and friction"}, {"id": "28efd126-6a7d-4166-9be8-95056da6f892", "type": "concept", "title": "Incentives and unintended consequences"}, {"id": "ff443a4a-0972-4c50-9060-b3e0743e7389", "type": "concept", "title": "Ethics of nudging and transparent design"}]}]}, {"id": "63ce332a-49ce-44b3-b6b4-8366f9849517", "type": "topic", "title": "Culturally Responsive Nutrition Education and Communication", "description": "Nutrition education is effective when it is relevant, understandable, respectful, and co-created. Students practice translating evidence into learning experiences and communication products for diverse audiences.", "children": [{"id": "908ba11a-4dc5-44ce-a11c-d974d6a2fb3f", "type": "subtopic", "title": "Culture, foodways, and cultural humility", "description": "Builds curiosity and self-awareness while rejecting stereotypes and one-size-fits-all advice.", "children": [{"id": "1883e81e-e831-4886-9795-88bff42618b9", "type": "concept", "title": "Food identity, migration, religion, family, and tradition"}, {"id": "6b6f699a-ac68-41b0-b7ea-432bf395e4c1", "type": "concept", "title": "Cultural humility, positionality, and power"}, {"id": "cb481e08-c8b3-4d0c-9f5c-f7ff9b0e756f", "type": "concept", "title": "Adaptation versus surface-level translation"}]}, {"id": "51f7a24e-99d9-40be-b9c0-2d33cb26086c", "type": "subtopic", "title": "Learning design and facilitation", "description": "Turns objectives into participatory experiences that build usable knowledge and skills.", "children": [{"id": "6b955323-8e4b-4e0c-aa77-7e50bd916f45", "type": "concept", "title": "Audience analysis and measurable learning objectives"}, {"id": "a5d503df-6b0f-429a-8815-0eedc233a603", "type": "concept", "title": "Adult learning, experiential learning, and peer education"}, {"id": "a17ac62d-159d-4d2c-bdb7-d872f9305c91", "type": "concept", "title": "Lesson sequencing, demonstrations, teach-back, and facilitation"}]}, {"id": "7131ec5f-f9fb-4209-a257-33a6f3ee5f6e", "type": "subtopic", "title": "Health literacy, numeracy, language, and accessibility", "description": "Ensures materials can be understood and used across literacy levels and access needs.", "children": [{"id": "e52b173e-6685-4c69-a0e2-ba9cd4f711eb", "type": "concept", "title": "Plain language and universal precautions"}, {"id": "d71025d3-0156-41f1-b3d0-24b31805d61c", "type": "concept", "title": "Risk and numerical communication"}, {"id": "b30e47de-40b3-4893-adb6-9059a85b338b", "type": "concept", "title": "Interpretation, translation, disability access, and inclusive formats"}]}, {"id": "a48fef95-1c17-4828-8280-12a20c3db5d4", "type": "subtopic", "title": "Digital communication and misinformation", "description": "Prepares students to communicate in online environments shaped by algorithms, influencers, and rapidly spreading claims.", "children": [{"id": "1ec56243-4e3d-409c-9a10-1262b5b8a186", "type": "concept", "title": "Social media campaign design and audience segmentation"}, {"id": "c56cf38f-d992-4956-b3bd-ede3206a6b7e", "type": "concept", "title": "Source verification and prebunking/debunking"}, {"id": "191d5224-937c-4bd1-b869-338c252ee819", "type": "concept", "title": "Ethical storytelling, privacy, and evaluation of digital reach"}]}]}, {"id": "94e6f9ff-ab6e-414a-ba19-423343d6358a", "type": "topic", "title": "Participatory Program Planning and Logic Models", "description": "This unit converts assessment evidence into a coherent, community-owned plan. Students build programs whose activities, resources, outcomes, and assumptions can be explained and tested.", "children": [{"id": "812e3785-3906-4173-9365-c8840fd002c2", "type": "subtopic", "title": "Partnership and participatory planning", "description": "Improves relevance, legitimacy, and sustainability by sharing power throughout the program cycle.", "children": [{"id": "e53a701b-44af-453e-a522-d3e1991a7762", "type": "concept", "title": "Community-based participatory principles"}, {"id": "43310e06-987a-49ac-9dc6-7d5ac3e2beed", "type": "concept", "title": "Compensation, governance, conflict, and accountability"}, {"id": "85ba4c9d-1695-433f-ac42-2cdeb5e13710", "type": "concept", "title": "Coalitions, memoranda of understanding, and facilitation"}]}, {"id": "8191c2af-aef4-497b-bbe8-ca2a9361a55d", "type": "subtopic", "title": "Goals, objectives, and intervention selection", "description": "Creates a defensible line from priority problem to achievable action.", "children": [{"id": "3e4d6fa3-43ba-4e04-8c89-21babc914fd6", "type": "concept", "title": "SMARTIE objectives"}, {"id": "27b77e8b-220c-4d91-9c8e-d00f3c37ff03", "type": "concept", "title": "Evidence-based and practice-based interventions"}, {"id": "eb404e91-a922-4b45-a8f0-e1c199bcc284", "type": "concept", "title": "Adaptation for context while preserving core functions"}]}, {"id": "fa06821b-c28f-47d5-9316-f079f5434973", "type": "subtopic", "title": "Logic models and theories of change", "description": "Makes causal assumptions visible and aligns activities with outcomes.", "children": [{"id": "c5122353-2145-41f4-ad7f-655c56ad9db5", "type": "concept", "title": "Inputs, activities, outputs, and short-/long-term outcomes"}, {"id": "7cebebdd-a3a2-48af-ae0c-3127dc68cc10", "type": "concept", "title": "Context, assumptions, moderators, and unintended effects"}, {"id": "07544796-c2ba-497d-8bb9-9c545498eae9", "type": "concept", "title": "Backward design and contribution versus attribution"}]}, {"id": "9490cae4-fe54-4508-9be0-7cf35d0a2047", "type": "subtopic", "title": "Work plans, budgets, and risk management", "description": "Develops the operational thinking needed to move from an idea to delivery.", "children": [{"id": "ec58f6b2-5488-4693-adea-15a37b228fb3", "type": "concept", "title": "Tasks, timelines, milestones, roles, and dependencies"}, {"id": "73f0c0e9-83e5-460d-b275-30b5a06f1498", "type": "concept", "title": "Direct/indirect costs, in-kind resources, and budget justification"}, {"id": "d0545dae-0cdc-4169-8ab5-ce0b8c8119e9", "type": "concept", "title": "Risk registers, safeguarding, contingency, and data plans"}]}]}, {"id": "15cc69aa-dd21-4288-99c7-e1ea4ee9aaaa", "type": "topic", "title": "Implementation Science, Partnerships, and Workforce", "description": "A program can be evidence-based yet fail in real settings. Students examine adoption, fidelity, adaptation, capacity, and sustainability across organizations and communities.", "children": [{"id": "f3ecfc19-c38f-4cb2-82b5-04546012416b", "type": "subtopic", "title": "Implementation outcomes and context", "description": "Provides a vocabulary for diagnosing why delivery succeeds or stalls.", "children": [{"id": "8695cd3a-09b0-4674-bfcb-f81c27dfb521", "type": "concept", "title": "Acceptability, adoption, appropriateness, feasibility, fidelity, cost, penetration, and sustainability"}, {"id": "3201d7c3-b1b6-419d-9cef-62f6215fe339", "type": "concept", "title": "Inner and outer setting influences"}, {"id": "72c366a2-cad2-4b11-9487-45cbf5fdc888", "type": "concept", "title": "Readiness, climate, leadership, and resources"}]}, {"id": "5657ee00-966f-4795-8665-deebb5852cc2", "type": "subtopic", "title": "Adaptation, fidelity, and quality improvement", "description": "Balances responsiveness to context with protection of the intervention's essential functions.", "children": [{"id": "702d76ab-d23b-4cb5-8b4f-a4d0e78a3f10", "type": "concept", "title": "Core components versus adaptable periphery"}, {"id": "55615544-45db-45b4-8c21-610b03c91182", "type": "concept", "title": "Plan–Do–Study–Act cycles"}, {"id": "4dedefb1-2bd2-488f-bae9-f1ba4e3360e1", "type": "concept", "title": "Implementation logs, fidelity checks, and rapid feedback"}]}, {"id": "5915dfef-eb21-4289-871f-42402a239d38", "type": "subtopic", "title": "Community health workers and peer models", "description": "Examines trusted workforce strategies that bridge services and lived experience.", "children": [{"id": "978b4f48-a59c-4880-a74d-8996970aaa79", "type": "concept", "title": "Roles, training, supervision, compensation, and career pathways"}, {"id": "813537d9-d92c-4dc8-9f8d-c1f7b31c8d17", "type": "concept", "title": "Peer educators, navigators, and promotores"}, {"id": "dc9dd1fe-0e40-4265-b5e3-4d6b999acfae", "type": "concept", "title": "Role clarity, burnout, safety, and ethical employment"}]}, {"id": "93002823-27f8-4cf3-8ab5-176ac5ab752d", "type": "subtopic", "title": "Sustainability and scale", "description": "Encourages planning for durable benefit beyond a pilot or grant period.", "children": [{"id": "44404351-e6a9-48a4-9a13-48099acf5493", "type": "concept", "title": "Institutionalization, financing, policy integration, and ownership"}, {"id": "7418f088-0f64-4d23-aaed-768c288a7a6c", "type": "concept", "title": "Scale-up, spread, and adaptation across sites"}, {"id": "f934cdb5-3ece-4841-a678-4f8a75285315", "type": "concept", "title": "De-implementation of ineffective or harmful practices"}]}]}, {"id": "f2005b21-0c72-4abf-97d6-b5d3e58de893", "type": "topic", "title": "Nutrition Policy, Advocacy, and Political Economy", "description": "Population nutrition is shaped by laws, budgets, institutions, and competing interests. Students learn to analyze policy options and communicate evidence within ethical professional boundaries.", "children": [{"id": "cf31d372-49cf-4eb5-a8d6-8fb46b57f9a0", "type": "subtopic", "title": "Policy process and instruments", "description": "Explains where and how nutrition policy decisions are made.", "children": [{"id": "92112f66-c72e-48ce-96af-53f2aca11c01", "type": "concept", "title": "Agenda setting, formulation, adoption, implementation, and evaluation"}, {"id": "ad2ea169-0da4-4c56-95a3-45d7a8b6fe96", "type": "concept", "title": "Regulation, taxation, subsidies, standards, procurement, and information tools"}, {"id": "0af6e606-9950-4552-95ca-b21293d6de1d", "type": "concept", "title": "Federal, state/provincial, local, institutional, and global authority"}]}, {"id": "c61cd615-3954-4fd5-aa27-8418953dc9c1", "type": "subtopic", "title": "Policy analysis", "description": "Provides a structured way to compare options beyond whether they sound appealing.", "children": [{"id": "8c0449f5-0a31-42ce-8b32-3af3a276edd0", "type": "concept", "title": "Effectiveness, equity, feasibility, cost, acceptability, and enforceability"}, {"id": "6f0ac343-b757-4975-9915-277d599bec64", "type": "concept", "title": "Distributional impact and health impact assessment"}, {"id": "718f017c-f72d-4b68-9c1f-cacee609d6c3", "type": "concept", "title": "Unintended consequences and policy coherence"}]}, {"id": "162a64ee-04e0-4ded-924e-14206087560b", "type": "subtopic", "title": "Advocacy and strategic communication", "description": "Builds lawful, evidence-informed participation in public decision-making.", "children": [{"id": "50040c30-eb6b-447a-888f-e5abe177984c", "type": "concept", "title": "Stakeholder and power mapping"}, {"id": "b584f27f-d73e-47e7-b3cf-695b16182054", "type": "concept", "title": "Policy briefs, testimony, public comment, and media engagement"}, {"id": "49efaf61-4687-426c-9416-4b338314fe79", "type": "concept", "title": "Coalition strategy and grassroots/grasstops approaches"}]}, {"id": "2293d2cf-132c-451c-879b-3f2d0f152f8b", "type": "subtopic", "title": "Industry influence and conflicts of interest", "description": "Develops critical awareness of lobbying, sponsorship, research funding, and corporate political activity.", "children": [{"id": "1db3f6a9-7c6e-4bdb-b5b5-06b3e9d8a048", "type": "concept", "title": "Commercial determinants and policy interference"}, {"id": "593528c3-3687-4caa-8c6a-2e98adc73617", "type": "concept", "title": "Transparency, disclosure, and conflict-management policies"}, {"id": "cdc617cc-873c-43c0-9104-1abd3472ace1", "type": "concept", "title": "Responsible public–private engagement"}]}]}, {"id": "d9b80662-3dfd-4c7e-8f90-8c62ef82a878", "type": "topic", "title": "Program Evaluation, Economic Thinking, and Learning", "description": "Evaluation is not an afterthought; it is how communities and funders learn whether a program was delivered, whom it reached, what changed, and at what cost. Students design feasible mixed-method evaluations.", "children": [{"id": "862f4089-b6c0-4f42-881b-a54ee81aa1c0", "type": "subtopic", "title": "Evaluation questions and designs", "description": "Aligns evaluation effort with decisions stakeholders actually need to make.", "children": [{"id": "e36c67f7-d79d-48be-8ca7-22fac3a8f635", "type": "concept", "title": "Formative, process, outcome, impact, and developmental evaluation"}, {"id": "9867b665-94be-4e21-9c49-b455914acb6e", "type": "concept", "title": "Experimental, quasi-experimental, pre–post, and contribution designs"}, {"id": "7aede296-0363-4cf9-898e-37e362fc79df", "type": "concept", "title": "Evaluability, comparison groups, and threats to validity"}]}, {"id": "4ec05174-8d9c-4985-823b-5240f19c39a9", "type": "subtopic", "title": "Indicators, measurement, and data collection", "description": "Translates objectives into valid, feasible, and equitable measures.", "children": [{"id": "952d63dc-de50-4348-9e47-186ea0ed8140", "type": "concept", "title": "Reach, dose, fidelity, behavior, environment, and health outcomes"}, {"id": "3313135f-109b-450d-812d-e2363f905100", "type": "concept", "title": "Quantitative and qualitative measures"}, {"id": "e62e3825-1c6a-4e8c-a76f-a6d15034bad6", "type": "concept", "title": "Validity, reliability, responsiveness, burden, and cultural relevance"}]}, {"id": "ca889ea3-15ab-4c63-a88e-d82248143622", "type": "subtopic", "title": "Analysis, interpretation, and equity", "description": "Teaches students to judge patterns carefully and avoid averages that hide differential effects.", "children": [{"id": "95552941-cc98-4a25-aa68-d4f5818acd9b", "type": "concept", "title": "Descriptive analysis and meaningful change"}, {"id": "1809fcfe-d209-410c-b6da-dcc6e4fa9643", "type": "concept", "title": "Subgroup and intersectional analysis"}, {"id": "4b9893c5-e067-4b39-83af-13646c4e0b81", "type": "concept", "title": "Triangulation, negative cases, and unintended outcomes"}]}, {"id": "e8d3caef-cc1d-4cc4-b6dc-db98214eb445", "type": "subtopic", "title": "Economic and dissemination considerations", "description": "Introduces resource stewardship and ensures findings return to those who contributed.", "children": [{"id": "530dfab4-ade6-446d-87e4-9f7f92599352", "type": "concept", "title": "Cost description, cost-effectiveness, affordability, and budget impact"}, {"id": "df0f8506-59a6-41a0-a229-14d6a5e6d2fc", "type": "concept", "title": "Data dashboards, briefs, presentations, and community reporting"}, {"id": "6f354d24-ede1-473d-a79b-a66bdf15fc43", "type": "concept", "title": "Utilization-focused recommendations and learning cycles"}]}]}, {"id": "ebf11d95-8e36-4587-a6e7-b46955e39e7b", "type": "topic", "title": "Sustainable Food Systems, Climate, and Emergency Nutrition", "description": "Nutrition security depends on resilient ecological and social systems. Students analyze food-system trade-offs and prepare for disruptions that disproportionately affect communities already facing inequity.", "children": [{"id": "2f6bbf37-371e-49ca-9d1b-d8f71ef5e499", "type": "subtopic", "title": "Food systems and sustainability", "description": "Connects diets with production, processing, distribution, labor, waste, and ecological limits.", "children": [{"id": "7df6d8ac-a2b7-403f-96ac-407213805a68", "type": "concept", "title": "Food-system actors and value chains"}, {"id": "2f6d9e82-ca08-4d4c-b899-b2b5bcbfd143", "type": "concept", "title": "Diet quality, environmental footprints, biodiversity, and animal welfare"}, {"id": "175b4af9-e6a8-49e0-9593-1c068541432e", "type": "concept", "title": "Just transition, labor conditions, and fair livelihoods"}]}, {"id": "8422e5c8-72b0-426d-9550-dbe284036d5c", "type": "subtopic", "title": "Local and institutional food strategies", "description": "Evaluates place-based approaches without assuming local automatically means equitable or sustainable.", "children": [{"id": "f1831878-6264-4862-87c7-9c6b105ed93b", "type": "concept", "title": "Farm-to-school, food hubs, gardens, and urban agriculture"}, {"id": "0553a2a8-1049-454d-9c75-d19b10ed7ef3", "type": "concept", "title": "Values-based procurement and institutional purchasing"}, {"id": "097c7aa7-67d5-4efd-babd-618dd6635156", "type": "concept", "title": "Food loss, waste prevention, recovery, and composting"}]}, {"id": "675c60af-53ea-4290-98c9-92c32c3fb1a2", "type": "subtopic", "title": "Climate change and nutrition", "description": "Explains pathways from climate hazards to food availability, affordability, safety, and disease.", "children": [{"id": "5f230110-4e09-4280-a571-61a3bdfed2b2", "type": "concept", "title": "Heat, drought, flooding, wildfire, and supply disruption"}, {"id": "413fd85e-cd32-47f4-b763-446e7cef6a28", "type": "concept", "title": "Climate-sensitive malnutrition and foodborne risk"}, {"id": "6bec9ee0-096c-4d3f-8044-747e59f556bc", "type": "concept", "title": "Mitigation, adaptation, resilience, and climate justice"}]}, {"id": "8d44cc99-e917-4b8b-9043-bac7216f3243", "type": "subtopic", "title": "Emergency and humanitarian nutrition", "description": "Builds readiness for ethical nutrition response during disasters and displacement.", "children": [{"id": "cf2d4dd3-a54f-4884-8963-3d0f448e9ffc", "type": "concept", "title": "Emergency preparedness and continuity of nutrition services"}, {"id": "72410084-642b-4777-8ba2-b65af76a1097", "type": "concept", "title": "Rapid assessment, shelters, feeding operations, and special dietary needs"}, {"id": "ba25053e-76d3-4839-91c0-6159a8e82577", "type": "concept", "title": "Infant feeding in emergencies, safeguarding, coordination, and recovery"}]}]}, {"id": "ec7e9ce8-36ba-424b-9752-041c67acdea4", "type": "topic", "title": "Ethics, Law, and Responsible Community Practice", "description": "Community nutrition professionals hold responsibilities to individuals, communities, employers, funders, and the public. This unit makes ethical reasoning, legal awareness, and responsible data practice explicit.", "children": [{"id": "c306befb-b807-4ea1-9bb7-b0a357e83bc9", "type": "subtopic", "title": "Ethical frameworks and professional conduct", "description": "Provides a disciplined way to resolve tensions among benefit, autonomy, justice, and duty.", "children": [{"id": "f039e635-ada2-467a-94c8-84eb24b65ab7", "type": "concept", "title": "Beneficence, nonmaleficence, autonomy, justice, solidarity, and reciprocity"}, {"id": "fd747933-3273-4aca-970c-1f59b907a002", "type": "concept", "title": "Professional codes, competence, and accountability"}, {"id": "0643af56-0414-49e5-a3b3-0b8c2feba984", "type": "concept", "title": "Moral distress, dual loyalty, and escalation pathways"}]}, {"id": "acab6939-c083-4bfa-b9fb-6394e87d91e9", "type": "subtopic", "title": "Consent, privacy, and community data governance", "description": "Protects participants while recognizing that communities can also experience collective harms.", "children": [{"id": "001f6c7e-aba5-48a5-8b09-e04b64fbb1df", "type": "concept", "title": "Informed consent and assent"}, {"id": "51bc5cd6-8e46-4ded-bb39-ee6ab7a08a76", "type": "concept", "title": "Confidentiality, data minimization, security, and secondary use"}, {"id": "afb99144-7ed0-48c6-8564-cb4b4dd69be8", "type": "concept", "title": "Data ownership, Indigenous data sovereignty, and community review"}]}, {"id": "7f2a6cb4-d5e8-4f5f-af6a-0e65d52f788d", "type": "subtopic", "title": "Research and evaluation ethics", "description": "Distinguishes service improvement from research while applying safeguards to both.", "children": [{"id": "def76a18-f2bd-4079-bb3c-b2cb19bed6a1", "type": "concept", "title": "Human-subjects review and quality-improvement boundaries"}, {"id": "ee2857ce-44f5-4567-8ed5-c1f769700c90", "type": "concept", "title": "Recruitment, incentives, vulnerable populations, and risk"}, {"id": "88321245-88f8-4177-add5-7fe74958b72e", "type": "concept", "title": "Returning results and benefit sharing"}]}, {"id": "1665ee96-0d87-4f48-ba5c-17b2ca8fcf72", "type": "subtopic", "title": "Stigma, weight bias, and respectful practice", "description": "Prevents nutrition interventions from reinforcing shame, discrimination, or eating pathology.", "children": [{"id": "aeb7e1b9-b393-4f3b-ad95-7b67901e02bc", "type": "concept", "title": "Person-first and identity-affirming language"}, {"id": "ab29980d-35d7-4896-a2fd-b2dc3b7cc3ec", "type": "concept", "title": "Weight-inclusive and trauma-informed approaches"}, {"id": "bcd40de1-a97f-45b9-8159-9e7b53943bfc", "type": "concept", "title": "Image selection, messaging audits, and harm monitoring"}]}]}, {"id": "55b0d84b-5488-49e2-8f22-c05f6744812e", "type": "topic", "title": "Community Nutrition Intervention Capstone", "description": "The capstone integrates assessment, theory, planning, implementation, evaluation, and communication into a partner-informed intervention proposal. It demonstrates readiness to contribute responsibly to real community nutrition work.", "children": [{"id": "5f505c4f-5074-4b69-bf0a-a1daa4f730d0", "type": "subtopic", "title": "Partner brief and evidence synthesis", "description": "Defines the community priority and decision context using credible data and community knowledge.", "children": [{"id": "20c59566-9583-417a-a082-9ca1be1b7156", "type": "concept", "title": "Community profile and asset/needs synthesis"}, {"id": "1181865c-4d0e-44ac-9c17-51e12aba50b9", "type": "concept", "title": "Stakeholder, equity, and systems analysis"}, {"id": "08e30da5-18b0-42df-9b6c-8bc6e7f0676c", "type": "concept", "title": "Focused evidence review and intervention rationale"}]}, {"id": "b1445f6d-41f6-4b4f-a2ff-e8e07d27ce02", "type": "subtopic", "title": "Intervention and implementation plan", "description": "Specifies what will happen, for whom, by whom, and under what conditions.", "children": [{"id": "9f87b2cb-0254-4762-9712-211ddfd261a8", "type": "concept", "title": "Theory of change and logic model"}, {"id": "99a75d55-0c0c-4492-a59d-7fe4e140a62e", "type": "concept", "title": "Culturally responsive activities and materials"}, {"id": "4c929867-7b17-4f79-8246-781c535b4b3d", "type": "concept", "title": "Work plan, roles, budget, adaptation, risk, and sustainability"}]}, {"id": "c9eee684-da01-49a2-bdc9-540b0becfce0", "type": "subtopic", "title": "Evaluation and knowledge-mobilization plan", "description": "Ensures the proposal can generate useful learning and communicate it accessibly.", "children": [{"id": "96a7f490-476d-47eb-a617-1ff747ce7ba5", "type": "concept", "title": "Evaluation questions, indicators, methods, and analysis"}, {"id": "63ba41bd-3131-4ed7-9ce6-83214842984a", "type": "concept", "title": "Ethics, privacy, and data governance"}, {"id": "d21da3bf-3eb5-4d37-9982-500c7d56bdf5", "type": "concept", "title": "Community-facing product, policy brief, and professional presentation"}]}, {"id": "cea56cc2-3d09-4cdd-b116-b5ad77ac224f", "type": "subtopic", "title": "Peer review and reflective practice", "description": "Develops the ability to give, receive, and apply critique while examining one's own assumptions and power.", "children": [{"id": "c4097528-8e41-43ba-85f6-c9368140d064", "type": "concept", "title": "Structured peer and partner feedback"}, {"id": "8c9bae07-627b-48fb-b25c-aa2dd759849c", "type": "concept", "title": "Revision memo and decision log"}, {"id": "1506961e-bcc0-4fc1-bb52-4d33fb76f73e", "type": "concept", "title": "Individual reflection on positionality, competence, and next steps"}]}]}], "dbBacked": true}$cnutjson$::jsonb,
